{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, COUNT(*) n, ROUND(AVG(value),2) avg_v FROM abnormal_metrics_sum WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='profile' GROUP BY ALL",
          "claim": "Profile deployment reports available=0 across the whole abnormal window, versus 1 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, COUNT(*) n, SUM(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, ROUND(MAX(duration)/1e6,2) max_ms FROM abnormal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY ALL",
          "claim": "All 677 frontend calls to profile fail in about 0.01 ms; no profile server spans exist in the abnormal period."
        }
      ]
    },
    {
      "service": "rate",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT CASE WHEN duration<1e6 THEN 'lt1ms' WHEN duration<1e9 THEN 'lt1s' ELSE 'gt1s' END bucket, COUNT(*) n FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "936 of 938 search calls to rate fail in under 1 ms, so no connection to rate is made."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, COUNT(*) n FROM abnormal_traces WHERE service_name='rate' GROUP BY ALL",
          "claim": "Rate emits no spans at all in the abnormal period, though normal had 855 rate server spans."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, COUNT(*) n, ROUND(AVG(value),4) avg_v FROM normal_metrics WHERE service_name='rate' AND metric='k8s.pod.cpu.usage' GROUP BY ALL UNION ALL SELECT service_name, metric, COUNT(*), ROUND(AVG(value),4) FROM abnormal_metrics WHERE service_name='rate' AND metric='k8s.pod.cpu.usage' GROUP BY ALL",
          "claim": "Rate pod CPU falls from about 0.0062 to 0.0008 while the pod stays up and restart counts are unchanged."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code code, COUNT(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /recommendations' GROUP BY ALL",
          "claim": "All 677 frontend /recommendations requests return HTTP 500 after the profile calls fail."
        }
      ]
    },
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, COUNT(*) n, SUM(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY ALL",
          "claim": "Every search rate.GetRates call errors, and every search.Search/Nearby server span errors with it."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code code, COUNT(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY ALL",
          "claim": "All 1118 frontend /hotels requests return HTTP 500 while their search calls fail."
        }
      ]
    }
  ]
}
